// Üretilen dosya: tool/ozgun/uret.py. Yabancı Dil · Türkçe yazım ve noktalama kuralları (zor).
const ozLanguage14Zor = <(String, String, List<String>, String)>[
  ('Ankara\'da bulunan arkadaşım bana kitap gönderdi. İkinci cümle \'Ayşe de İstanbul\'da okuyor.\' Bu iki cümledeki \'da/de\'lerin yazımı için hangisi doğrudur?', 'İlk cümledeki \'da\' ek olduğu için bitişik, ikincideki \'de\' bağlaç olduğu için ayrı yazılır.', ['İkisi de ek olduğu için kesme işaretinden sonra bitişik yazılır.', 'İkisi de bağlaç olduğu için ayrı yazılır.', 'İlk cümledeki \'da\' ayrı, ikincideki \'de\' bitişik yazılmalıdır, çünkü ikisi de ektir.'], 'Ankara\'da\' ve \'İstanbul\'da\' bulunma ekidir ve bitişiktir. \'Ayşe de\' ise bağlaçtır ve ayrı yazılır.'),
  ('\'Siz bu filmi daha önce izlemiş miydiniz?\' cümlesinde soru ekine bağlanan \'-ydiniz\' için hangisi doğrudur?', 'Ek fiilin geçmiş biçimi ve kişi eki soru ekine bitişik yazılır.', ['Ek fiil ve kişi eki ayrı yazılır.', 'Ek fiil sözcüğe, kişi eki soru ekine bitişir.', 'Yalnız kişi eki ayrı yazılır, ek fiil soru ekine bitişir.'], 'Soru ekinden sonra gelen ek fiil ve kişi ekleri (\'miydiniz\') soru ekine bitişik yazılır.'),
  ('\'Atatürk Anıtkabir\'de yatıyor.\' ile \'Başkentimiz Ankara\'dır.\' cümleleri karşılaştırıldığında \'Ankara\'dır\' yazımında ne gözlenir?', 'Özel adla ek fiil arasına kesme işareti konmuştur ve ek bitişiktir.', ['Ek fiil ayrı yazılmıştır.', 'Kesme işareti yoktur; ek doğrudan bitişir.', 'Ek fiil ile özel ad arasına kısa çizgi konmuş, ek ayrı yazılmıştır.'], 'Özel adlara gelen ekler, ek fiil de dahil, kesme işaretiyle ayrılır: \'Ankara\'dır\'.'),
  ('Aşağıdaki sözcüklerden hangisinde birleşme sırasında ses düşmesi vardır ve sözcük bitişik yazılır?', 'kaynana', ['su yolu', 'kara yol', 'göz yaşı'], '\'Kayın ana\' sözcükleri birleşirken \'ı\' düşmüş ve \'kaynana\' oluşmuştur. Bitişik yazılır.'),
  ('Aşağıdaki seçeneklerden hangisinde bir ikileme ile bir pekiştirme sıralı olarak verilmiştir?', 'ev bark – apaçık', ['yemyeşil – bembeyaz', 'ağır ağır – yavaş yavaş', 'dümdüz – kapkara'], '\'Ev bark\' ikileme, \'apaçık\' ise pekiştirmedir. Diğer seçenekler aynı türdendir.'),
  ('\'Perşembe günü toplantı var.\' ile \'7 Mayıs 2015 Perşembe günü toplantı vardı.\' cümleleri arasındaki yazım farkı nedir?', 'Belirli tarih verilince gün ve ay adları büyük harfle yazılır.', ['İkisinde de gün adı büyük yazılır.', 'İkisinde de gün adı küçük yazılır.', 'İkinci cümlede yalnız ay adı küçük, gün adı büyük yazılır.'], 'Belli bir tarih bildirmeyen gün ve ay adları küçük harfle başlar; belirli tarihin parçası olduklarında büyük harfle yazılırlar.'),
  ('\'Okulumuzun müdürü cuma günü bizi toplayıp konuştu.\' cümlesindeki \'cuma\' ve \'müdürü\' sözcükleri küçük yazılmıştır. Bu yazım için hangisi doğrudur?', 'Doğrudur; ne belirli tarih ne de özel ada bağlı unvan vardır.', ['Yanlıştır; gün adları her zaman büyük yazılır.', 'Yanlıştır; \'müdürü\' büyük başlamalıdır.', 'Doğrudur; ama \'okulumuzun\' sözcüğü de cümle içinde büyük yazılmalıdır.'], 'Yalnız özel ada eklenen unvanlar (\'Müdür Ali Bey\') ve belirli tarihler büyük yazılır. Genel kullanımlarda küçük harf geçerlidir.'),
  ('Aşağıdaki cümlelerden hangisinde kısaltmaya gelen ek yanlış yazılmıştır?', 'TRT\'nın haber saatleri değişti.', ['TDK\'nin sözlüğü yayımlandı.', 'ABD\'de çalışıyormuş.', 'THY\'nin uçağı rötarlı geldi.'], '\'TRT\' son harfi \'te\' diye okunduğu için ek \'nin\' olmalı: \'TRT\'nin\'. \'TRT\'nın\' yanlıştır.'),
  ('Aşağıdakilerden hangisinde yüzdelik ifadeye gelen ek doğru biçimde yazılmıştır?', 'Öğrencilerin %20\'si ödevini yapmamış.', ['Öğrencilerin %20si ödevini yapmamış.', 'Öğrencilerin % 20 si ödevini yapmamış.', 'Öğrencilerin %20 \'si ödevini yapmamış.'], 'Rakam ve işaretlere gelen ekler kesme işaretiyle ayrılır: \'%20\'si\'.'),
  ('Bir kişinin gösterişsiz, alçakgönüllü olmasını anlatan sözcüğün doğru yazımı hangisidir?', 'mütevazı', ['mütevazi', 'mütevâzı yerine mütavazı', 'mütövazı'], 'TDK yazımı \'mütevazı\'dır.'),
  ('Aşağıdakilerden hangisi TDK Yazım Kılavuzu\'na göre doğru yazılmış bir sözcüktür?', 'rüzgâr', ['rüzgar', 'rüzgârr', 'rüzgâar'], '\'Rüzgâr\' sözcüğünde \'g\' ünsüzünden sonra gelen \'a\' ünlüsü inceltildiği için şapka kullanılır.'),
  ('\'Okul müdürüne yazılan kâğıt\' ifadesindeki \'kâğıt\' sözcüğünde şapkanın görevi nedir?', '\'k\' ünsüzünden sonra gelen \'a\' ünlüsünü inceltmek', ['\'ğ\' harfini sesli okutmak', 'Sözcüğü yabancı kökenli göstermek', 'Sözcüğü çoğul yapmak'], '\'Kâğıt\' sözcüğündeki şapka, ince okunan \'k\'dan sonra gelen \'a\'nın inceltilmesini gösterir.'),
  ('\'Yol\' sözcüğüne \'-cu\' eki getirilirse hangi yazım doğrudur ve neden?', 'yolcu; çünkü \'l\' yumuşak (sürekli) ünsüzdür, \'cu\' ekinde değişim olmaz.', ['yolçu; çünkü \'l\' sert ünsüzdür, ek \'çu\' olmalıdır.', 'yol cu; çünkü ek ayrı yazılmalıdır.', 'yolcu; çünkü \'yol\' sözcüğü sert ünsüzle bitmektedir.'], '\'l\' sert ünsüzlerden (fıstıkçı şahap) biri olmadığı için ek \'cu\' kalır: \'yolcu\'.'),
  ('\'Kitapta yazan bir bilgi\' ifadesindeki \'ta\' ile bağlaç olan \'da\' arasında nasıl bir yazım farkı vardır?', '\'Ta\' bulunma ekidir, benzeşmeyle oluşmuştur; bağlaç \'da\' benzeşmeye girmez.', ['İkisi de ek olduğundan benzeşir.', 'İkisi de bağlaç olduğundan ayrı yazılır.', '\'Ta\' bağlaçtır; \'da\' bulunma ekidir.'], 'Bulunma eki benzeşmeye uğrar ve bitişik yazılır; bağlaç ise hep \'de/da\' ve ayrıdır.'),
  ('\'Bu sorunu çözmek ___ çok çalışmam gerekti.\' boşluğa gelecek \'için\' edatına eklenen \'de\' bağlacı ile birlikte hangi yazım doğrudur?', 'için de', ['içinde', 'için-de', 'içinde ayrı'], '\'İçin de\' (bağlaç) ayrı yazılır; bitişik yazılan \'içinde\' ise yer-durum bildirir.'),
  ('\'Duygularını hissediyorum\' cümlesinde \'his\' + \'etmek\'ten oluşan \'hissetmek\' fiilinde hangi yazım kuralı uygulanmıştır?', 'Ünsüz ikizleşmesi olduğu için bitişik yazılır.', ['Ünlü düşmesi olduğu için ayrı yazılır.', 'Ses olayı olmadığı için ayrı yazılır.', 'Kısaltma yapıldığı için nokta konur.'], '\'His\' + \'et-\' birleşirken \'s\' ünsüzü ikizleşir; sözcük bitişik yazılır.'),
  ('Televizyonda bir filmi izlemek anlamındaki \'seyir\' + \'etmek\' birleşiminde ses düşmesi vardır. Doğru yazım hangi seçenektedir?', 'seyretmek', ['seyir etmek', 'seyiretmek', 'seyr etmek'], '\'Seyir\' sözcüğünün son ünlüsü düşer ve sözcük bitişik yazılır: \'seyretmek\'.'),
  ('\'Ziyaret etmek\' ve \'telefon etmek\' fiilleri ile \'şükretmek\' fiilinin yazım farkı ne ile açıklanır?', 'Birincilerde ses olayı yoktur, ayrı yazılır; \'şükretmek\'te ünlü düşer, bitişik yazılır.', ['Tüm fiillerde ses olayı vardır, bu yüzden bitişik yazılırlar.', 'Tüm fiillerde ses olayı yoktur, bu yüzden tümü ayrı yazılır.', 'Yalnız \'şükretmek\' yabancı kökenli olduğu için bitişik yazılır.'], 'Bileşik fiillerde ses düşmesi, türemesi veya ikizleşmesi varsa bitişik, yoksa ayrı yazılır.'),
  ('\'Ben okula, kardeşim işe gitti.\' cümlesinde virgül hangi amaçla kullanılmıştır?', 'Ortak yüklemli iki öğeyi birbirinden ayırmak için', ['Hitap belirtmek için', 'Sıralı sıfatları ayırmak için', 'Ara söz belirtmek için'], 'Birinci cümlenin yüklemi eksiltilmiştir; ortak yüklemli yargılar virgülle ayrılır.'),
  ('Aşağıdaki cümlelerden hangisinde virgül gereksiz yere kullanılmıştır?', 'Öğretmen, sınıfa girdi.', ['Öğretmen yeni kitabı sınıfa getirdi, sonra dersi başlattı.', 'Evet, yarın gelirim.', 'Ali, gel buraya.'], 'Özne ile yüklem arasına, anlamı bozacak biçimde, virgül konmaz.'),
  ('Aşağıdaki cümlelerin hangisinde \'da\' ile sıralanan öğeler arasındaki virgül doğrudur?', 'Ali de, Veli de geldi.', ['Ali de Veli de, geldi.', 'Ali, de Veli de geldi.', 'Ali de Veli, de geldi.'], 'Tekrarlanan bağlaçlarla sıralanan öğeler arasına virgül konur.'),
  ('\'Sınava çok çalıştı; ama başarılı olamadı.\' cümlesinde \'ama\'dan önce noktalı virgül konmasının nedeni nedir?', 'Karşıtlığı daha belirgin bir duraklamayla göstermek', ['\'Ama\' sözcüğünü hitap yapmak', 'Cümleyi soruya çevirmek', 'Ara söz olduğunu belirtmek'], '\'Ama, fakat\' öncesinde virgül yerine noktalı virgül kullanılarak daha uzun bir durak sağlanabilir.'),
  ('\'Ahmet, şunları söyledi: Yarın gelmeyeceğim.\' cümlesinde iki noktadan sonraki ifadenin başlangıç harfi için hangisi doğrudur?', 'İfade tam bir cümle ise büyük harfle başlayabilir.', ['Hiçbir zaman büyük harfle başlamaz, hep küçük kalır.', 'Her zaman bütün harfleri büyük yazılır.', 'Sadece noktalama varsa büyük yazılır.'], 'İki noktadan sonra gelen bölüm bağımsız bir cümle ise büyük harfle başlayabilir; sıralama ise küçük harfle sürer.'),
  ('Üç noktadan sonra gelen sözcüğün büyük ya da küçük başlaması için hangisi doğrudur?', 'Cümle bittiyse büyük, sürüyorsa küçük harfle başlar.', ['Her zaman büyük harfle başlar.', 'Her zaman küçük harfle başlar, hiç değişmez.', 'Bütün harfler büyük yazılır.'], 'Üç nokta cümleyi bitiriyorsa sonraki cümle büyük harfle, düşünce sürüyorsa küçük harfle devam eder.'),
  ('\'Ali! Buraya gel.\' cümlesinde \'Ali\'den sonra konan ünlem işareti için hangisi doğrudur?', 'Hitap sözcüğünden sonra ünlem konduğunda sonraki cümle büyük harfle başlar.', ['Hitap sözcüğünden sonra ünlem konduğunda sonraki cümle küçük harfle başlar.', 'Hitap sözcüğünden sonra ünlem hiçbir zaman konmaz, yalnız virgül kullanılır.', 'Hitap sözcüğünden sonra ünlem yalnız soru cümlelerinde konur.'], 'Hitap sonrasında virgül ya da ünlem kullanılabilir; ünlemden sonra yeni cümle büyük harfle başlar.'),
  ('Tırnak içinde başka bir tırnaklı söz gerektiğinde iç tırnak için hangisi kullanılır?', 'Tek tırnak (\'...\')', ['Çift tırnak ("...") yine', 'Yay ayraç ((...))', 'Köşeli ayraç ([...])'], 'Tırnak içindeki ikinci tırnak tek tırnak olarak yazılır: "Ali \'geliyorum\' dedi."'),
  ('Parantez içindeki bir açıklama cümlenin sonunda yer alıyorsa noktanın yeri hangisidir?', 'Parantezden sonra, cümlenin sonunda', ['Parantezin içinde, ilk sözcükten sonra', 'Parantezden önce, ilk sözcükten sonra', 'Nokta hiç konmaz'], 'Cümlenin parçası olan parantez içi açıklamadan sonra cümle noktası konur.'),
  ('Yay ayraç içinde yine bir ayraç gerekirse iç ayraç hangisi olur?', 'Köşeli ayraç', ['Süslü ayraç', 'Tırnak işareti', 'Kısa çizgi ile'], 'Parantez içindeki ikinci açıklama köşeli ayraç ile gösterilir.'),
  ('Dil biliminde bir sesin okunuşunu göstermek için yazıda hangi ayraç kullanılır?', 'Köşeli ayraç', ['Yay ayraç', 'Tırnak işareti', 'Eğik çizgi ile'], 'Fonetik yazımda ses değerleri köşeli ayraç içine alınır.'),
  ('\'Fiil kökü: gel-\' ifadesindeki kısa çizgi neyi gösterir?', 'Köke ek geleceğini', ['Sözcüğün satır sonunda bölündüğünü', 'Bir tarih aralığını', 'Konuşma çizgisi olduğunu'], 'Kök veya gövde ek almadan önce kısa çizgiyle yazılır: \'gel-\'.'),
  ('\'Kısa çizgi\' ile \'uzun çizgi\' arasındaki temel işlev farkı nedir?', 'Kısa çizgi ilişki/bölme için, uzun çizgi konuşma ve ara söz için kullanılır.', ['Kısa çizgi konuşma için, uzun çizgi hecelemek için kullanılır; bu işlevler karışmaz.', 'İkisi her yerde yer değiştirebilir.', 'Kısa çizgi soru, uzun çizgi ünlem içindir.'], 'Kısa çizgi birleştirir ya da böler; uzun çizgi (tire) konuşmayı ve ara cümleyi göstermede kullanılır.'),
  ('\'Ayşe/Ahmet\' yazımında eğik çizginin kullanım hatası olmaması için hangisi doğrudur?', 'Eğik çizgi iki öğe arasında boşluksuz yazılır.', ['Eğik çizgi önünde ve sonunda iki boşlukla yazılır.', 'Eğik çizgi sözcüğün sonuna eklenir.', 'Eğik çizgi yalnız kısaltmalarda kullanılır.'], 'Eğik çizgi iki öğeyi birbirinden ayırır ve yanlarında genelde boşluk bırakılmaz.'),
  ('\'Beş kilometre\' ile \'beş kilometre/saat\' hız ifadesindeki eğik çizginin görevi nedir?', '\'Her\' anlamı katarak birimler arasında oran kurmak', ['Alternatif belirtmek ve ayırmak', 'Yıl aralığı göstermek', 'Konuşma başlatmak'], 'Bileşik birimlerde eğik çizgi oran anlamı taşır: \'km/sa\'.'),
  ('Madde madde sıralanan öğelerin sonunda hangi işaretin kullanılması tutarlıdır?', 'Tümünde aynı işaretin, ya nokta ya virgülün, kullanılması', ['Yalnız ilkinde nokta kullanılması, öbürlerinde işaret kullanmaması', 'Yalnız sonuncusunda virgül kullanılması', 'Her birinde iki nokta kullanılması'], 'Sıralamada işaret tutarlı olmalıdır; maddeler cümleyse nokta, kısa öğeyse virgül kullanılabilir.'),
  ('Konuşma çizgisiyle yazılan \'— Nereye gidiyorsun? diye sordu.\' cümlesindeki yazım için hangisi doğrudur?', 'Konuşma büyük harfle başlar; \'diye\' küçük harfle sürer.', ['Konuşma küçük harfle başlar.', '\'Diye\' büyük harfle başlar, çünkü cümle yenidir.', 'Tüm sözcükler küçük harfle yazılır.'], 'Konuşma çizgisinden sonra konuşma büyük harfle başlar; aktarma bölümü ise küçük harfle sürer.'),
  ('Satır sonuna sığmayan \'okul\' sözcüğü için hangisi doğrudur?', 'Bölünemez; \'o-kul\' biçimi tek harfi satır sonunda bırakır.', ['\'o-kul\' biçiminde bölünebilir.', '\'ok-ul\' biçiminde bölünebilir.', '\'oku-l\' biçiminde bölünebilir ve devam eder.'], 'Satır sonunda tek harf bırakılamaz; \'okul\' bu nedenle bölünmeden bir sonraki satıra geçer.'),
  ('Gün adının yanlış büyük harfle yazıldığı cümleyi bulunuz.', 'Biz her Cuma pazara giderdik.', ['Cumartesi günü maç var.', '7 Mayıs 2015 Perşembe günü toplandık.', 'Pazartesi sabahı erken kalktı.'], 'Belirli tarihi olmayan gün adı küçük harfle yazılır: \'her cuma\'.'),
  ('Hangi cümlede dağıtma sayı sıfatı yanlış yazılmıştır?', 'Çocuklara ikiser şeker verildi.', ['Çocuklara ikişer şeker verildi.', 'Öğrenciler üçer kişilik gruplar kurdu.', 'Herkese beşer kalem düştü.'], '\'İki\' sözcüğünden sonra ünlü ile başlayan \'-şer\' eki gelir: \'ikişer\'.'),
  ('Kısaltmaya gelen ek, hangi cümlede okunuşa uyulmadan hatalı getirilmiştir?', 'TRT\'nın haberlerini izledim.', ['TDK\'nin sözlüğünü aldım.', 'THY\'nin uçağı geç kaldı.', 'TBMM\'nin kararı açıklandı.'], '\'TRT\' kısaltması \'te-re-te\' okunduğundan ek \'nin\' olur: \'TRT\'nin\'.'),
  ('\'Çocuklar bahçede oynuyor annemler çay içiyor.\' cümlesinde en uygun noktalama düzeltmesi hangisidir?', 'Çocuklar bahçede oynuyor; annemler çay içiyor.', ['Çocuklar bahçede oynuyor: annemler çay içiyor.', 'Çocuklar bahçede oynuyor annemler, çay içiyor.', 'Çocuklar, bahçede oynuyor annemler çay içiyor.'], 'İki bağımsız yargı arasına virgül veya noktalı virgül konur; burada noktalı virgül uygundur.'),
  ('\'TRT\'nın haberlerini izledim.\' cümlesinde ek yazımı nasıl düzeltilmelidir?', '\'TRT\'nin\' biçimine çevrilerek', ['\'TRT\'ın\' biçimine çevrilerek, çünkü son harf ünsüzdür', '\'TRT\'yın\' biçimine çevrilerek', '\'TRT ın\' biçimine çevrilerek'], 'Kısaltmaya gelen ek okunuşa göre seçilir: \'te\' okunduğu için \'nin\'.'),
  ('\'Kağıt bitmiş!\' diye bağırdı. cümlesinde yazım bakımından hangi düzeltme zorunludur?', '\'Kağıt\' yerine \'Kâğıt\' yazılmalıdır.', ['\'bitmiş\' sözcüğü ünlemden önce büyük yazılmalıdır.', '\'diye\' sözcüğü \'di\' ve \'ye\' olarak ayrı yazılmalıdır.', '\'bağırdı\' sözcüğü kısaltılmalıdır.'], 'TDK yazımı \'kâğıt\'tır.'),
  ('\'Sende bir şey var.\' ile \'Sen de bir şey söyle.\' cümleleri arasındaki yazım farkının nedeni nedir?', 'İlkinde \'de\' bulunma eki, ikincisinde bağlaçtır.', ['İkisi de bulunma ekidir ancak anlam farklıdır.', 'İkisi de bağlaçtır, yalnız vurgu değişir.', 'İlkinde \'de\' pekiştirme, ikincisinde yönelme ekidir.'], '\'Sende\' = \'sende olan\' anlamında ek; \'sen de\' = \'sen dahi\' anlamında bağlaç.'),
  ('\'Ne ben de sen o toplantıya gitmedik.\' cümlesinde bağlaç yanlış kullanıldığı için hangi düzeltme gerekir?', '\'Ne ben de sen\' yerine \'Ne ben ne de sen\' yazılmalıdır.', ['\'de\' sözcüğü sonraki sözcüğe bitişik yazılmalıdır, çünkü ektir.', '\'Ne\' sözcüğü bitişik yazılmalıdır: \'Neben\', \'Nesen\' gibi.', '\'de\' sözcüğü kaldırılıp yerine \'ki\' bağlacı yazılmalıdır.'], '\'Ne ... ne de\' olumsuz bağlaç grubudur; \'de\' ayrı yazılır.'),
  ('\'Yemek ___ yedin, para ___ kazandın?\' cümlesinde boşluklara getirilecek soru ekleri için ünlü uyumu açısından hangisi doğrudur?', '\'Yemek\' sözcüğü için \'mi\', \'para\' sözcüğü için \'mı\'', ['İkisi için de \'mi\' gelir, çünkü ikisi de ince ünlülüdür', '\'Yemek\' için \'mı\', \'para\' için \'mi\' gelir', 'İkisi için de \'mı\' gelir, çünkü ikisi de açık ünlülüdür'], '\'Yemek\' sözcüğünün son ünlüsü \'e\' (ince), \'para\'nın \'a\' (kalın) olduğundan ek buna uyar.'),
  ('\'Okula gidiyor muydun?\' sorusunda \'muydun\' için hangisi doğrudur?', '\'Mu\' soru eki, \'-ydun\' ek fiil + kişi ekidir; bitişik yazılır.', ['\'Mu\' ile \'-ydun\' birbirinden ayrı yazılır.', '\'Mu\' fiile bitişir, \'-ydun\' ayrı kalır ve ayrı yazılır.', '\'Muydun\' her zaman büyük harfle yazılır, ayrılmaz.'], 'Soru ekinden sonra gelen ek fiil ve kişi eki soru ekine bitişir.'),
  ('\'Okula gittiyse\' sözcüğü ile \'okula gitti ise\' ifadeleri arasındaki yazım ilişkisi nedir?', 'Aynı anlamdadır; \'ise\' kısaltılınca \'-yse\' olarak bitişir.', ['Farklı anlamdadır; biri şart, öbürü zaman bildirir.', 'İkisi de bitişik yazılmalıdır, çünkü ektir.', 'İkisi de ayrı yazılmalıdır, çünkü ikisi de bağlaçtır.'], 'Şart ek fiili \'ise\' hem ayrı hem de kısaltılarak bitişik yazılabilir.'),
  ('Yabancı özel adların yazımı için aşağıdakilerden hangisi doğrudur?', 'Özgün yazımıyla yazılır; ekler okunuşa göre getirilir.', ['Okunuşa göre Türkçeleştirilerek yazılır, aslı gösterilmez.', 'Tümü büyük harfle yazılır, ekler eklenmez.', 'Her harfi ayrı okunacak biçimde yazılır, ekler okunmaz.'], 'TDK, yabancı özel adların aslına uygun yazılmasını, eklerin okunuşa göre getirilmesini ister.'),
  ('\'Shakespeare\' adına ilgi eki getirilirse hangi yazım TDK kuralına uygundur?', 'Shakespeare\'in', ['Shakespeare\'nin', 'Shakespeare\'ın', 'Shakespearein'], 'Ek, özel adın okunuşuna (\'şekspir\') göre seçilir ve kesmeyle ayrılır.'),
  ('Aşağıdaki cümlelerden hangisi doğru yazılmıştır?', 'Yarın ya da öbür gün kâğıtları teslim edeceğiz.', ['Yarın yada öbür gün kâğıtları teslim edeceğiz.', 'Yarın ya da öbür gün kağıtları teslim edeceğiz sanırım.', 'Yarın ya da öbürgün kâğıtları teslim edeceğiz.'], 'İlk seçenekte \'ya da\' ayrı, \'öbür gün\' ayrı ve \'kâğıt\' şapkalı yazılmıştır.'),
  ('Aşağıdaki cümlelerden hangisi, kısaltma ve ölçü birimi bakımından doğrudur?', 'Prof. Dr. Ahmet Bey 80 kg ağırlığında bir paket aldı.', ['Prof. Dr. Ahmet bey 80 kg. ağırlığında bir paket aldı.', 'Prof Dr Ahmet Bey 80 kg ağırlığında bir paket aldı.', 'Prof. Dr. Ahmet Bey 80 kgr ağırlığında bir paket aldı.'], 'Unvan kısaltmaları nokta alır, \'Bey\' büyük yazılır ve \'kg\' noktasız küçük harfle yazılır.'),
  ('Aşağıdaki cümlelerden hangisinde \'ki\' ve \'de\'nin yazımı doğrudur?', 'Duydum ki sen de yarın gelecekmişsin.', ['Duydumki sen de yarın gelecekmişsin.', 'Duydum ki sende yarın gelecekmişsin.', 'Duydum ki sen de yarın gelecek mişsin.'], 'Bağlaç \'ki\' ve bağlaç \'de\' ayrı yazılır; ek fiil sözcüğe bitişiktir.'),
  ('\'Dünkü toplantıda Mehmet bey TBMM\'nın kararını açıkladı.\' cümlesinde kaç yazım yanlışı vardır?', 'iki', ['bir', 'üç', 'dört'], '\'Mehmet Bey\' büyük harfle ve \'TBMM\'nin\' biçiminde yazılmalıdır; \'dünkü\' doğrudur.'),
  ('\'Okulumuzun müdürü ile Müdür Ayşe Hanım konuştu.\' türünden bir cümlede unvanın yazımı için hangisi doğrudur?', 'Özel adla birlikte kullanılan unvan büyük harfle başlar.', ['Unvan her zaman küçük harfle yazılır, adın önünde bile.', 'Unvan her zaman büyük harfle yazılır, genel kullanımda bile.', 'Unvan yalnızca satır başında büyük yazılır, başka yerde küçüktür.'], 'Kişi adının önünde yer alan unvan, adla birlikte kullanılınca büyük harfle başlar.'),
  ('Aşağıdakilerden hangisinde büyük harf kullanımı yanlıştır?', 'Doğu Anadolu\'da kış uzun sürer, bu yüzden Güneye gitti.', ['Güneydoğu Anadolu Bölgesi\'nde pamuk yetişir ve satılır.', 'Fırat Nehri bu bölgeden geçerek ilerler.', 'Marmara Denizi bir iç denizdir.'], 'Yön adı, bölge adı olmadıkça küçük yazılır: \'güneye\'.'),
  ('\'ABD\' kısaltmasına \'-li\' yapım eki gelirse doğru yazım hangisidir?', 'ABD\'li', ['ABDli', 'ABD li', 'A.B.D.\'li'], 'Kısaltmalara gelen ekler, yapım eki olsa bile kesmeyle ayrılır.'),
  ('\'Ankaralılar\' sözcüğünde kesme işareti bulunmamasının nedeni nedir?', 'Özel addan türeyen sözcüklerde yapım ekinden önce kesme kullanılmaz.', ['Ankara sözcüğünün genel ad olması ve ek almaması', 'Çokluk ekinin yapım eki olması ve özel adı değiştirmesi', 'Sözcüğün çok uzun olması ve kesmeyi gereksiz kılması'], '\'-lı\' yapım ekidir; türemiş sözcük genel ad kabul edilir ve \'-lar\' eki bitişik yazılır.'),
  ('\'18. yüzyılda\' ifadesinde kesme işareti kullanılmaması neyi gösterir?', 'Rakamdan sonra nokta varken ek kesmesiz bitişik gelir.', ['Hata yapıldığını', 'Sayının yanlış yazıldığını', 'Ekin eksik olduğunu'], '\'18. yüzyılda\' yazımında ek, noktadan sonra gelen sözcüğe aittir; kesme gerekmez.'),
  ('\'Birtakım insanlar bu fikre karşı çıktı.\' cümlesindeki belgisiz sıfatın yazımı için hangisi doğrudur?', 'Bitişik yazılır: \'birtakım\'.', ['Ayrı yazılır: \'bir takım\'.', 'Kısa çizgiyle yazılır.', 'Büyük harfle başlar.'], '\'Birtakım\' belirsizlik bildiren tek sözcüktür; \'bir takım elbise\' ise ayrı yazılır.'),
  ('\'Bir takım elbise aldım.\' ile \'Birtakım insanlar geç geldi.\' cümleleri arasındaki yazım farkının nedeni nedir?', 'İlkinde \'takım\' bir ad olarak ayrı, ikincisinde belgisiz sıfat olarak bitişik yazılır.', ['İkisi de belgisiz sıfattır, ikisi de bitişiktir.', 'İkisi de ad olduğu için ikisi de ayrıdır.', 'İlkinde yazım hatası vardır.'], '\'Birtakım\' belirsiz sayıyı anlatan tek sözcüktür; \'bir takım elbise\' ise sayı sıfatı ve ad grubudur.'),
  ('\'Mart ayında hava soğuktu ___ kar yağdı.\' cümlesindeki boşluğa \'hatta\' sözcüğü getirilirse yazım hangisi olur?', 'Mart ayında hava soğuktu, hatta kar yağdı.', ['Mart ayında hava soğuktu, hatta kar yağdı', 'Mart ayında hava soğuk tu hatta kar yağdı.', 'Mart ayında hava soğuktu hat ta kar yağdı.'], '\'Soğuktu\' ek fiille bitişik, \'hatta\' tek sözcük olarak yazılır.'),
  ('Bir şiirde dizeler satır satır yazıldığında dize sonlarındaki noktalama için hangisi doğrudur?', 'Cümle bittiğinde nokta konur; bitmediğinde uygun bir noktalama kullanılır.', ['Her dize sonuna mutlaka nokta konur.', 'Dize sonlarında hiçbir noktalama kullanılmaz.', 'Her dize sonuna ünlem konur.'], 'Şiirde de anlam bütünlüğüne göre noktalama yapılır; dize sonu otomatik nokta gerektirmez.'),
  ('\'Ankara\'lı arkadaşım geldi.\' cümlesinde ihlal edilen kural hangisidir?', 'Yapım ekleri özel adlardan kesmeyle ayrılmaz.', ['Özel adlara getirilen çekim ekleri kesme işaretiyle ayrılır.', 'Genel adlara gelen ekler kesme işaretiyle ayrılmaz.', 'Kısaltmaya gelen ek, kısaltmanın okunuşuna göre getirilir.'], '\'-lı\' yapım ekidir; özel addan kesmeyle ayrılmaz: \'Ankaralı\'.'),
  ('\'TRT\'ın haberini izledim.\' cümlesindeki ek hangi kuralı ihlal eder?', 'Kısaltmaya gelen ek, kısaltmanın okunuşuna göre getirilir.', ['Özel adlara getirilen çekim ekleri kesme işaretiyle ayrılır.', 'Genel adlara gelen ekler kesme işaretiyle ayrılmaz.', 'Yapım ekleri özel adlardan kesmeyle ayrılmaz.'], 'Kısaltmaya gelen ek okunuşa göre seçilir: \'TRT\'nin\'.'),
  ('\'Ne var ki\' ve \'ne de olsa\' kalıplarının yazımı için hangisi doğrudur?', 'Sözcükleri ayrı yazılır.', ['Her ikisi de bitişik yazılır: \'nevarki\', \'nedeolsa\'.', '\'Ne var ki\' bitişik, \'ne de olsa\' ayrı yazılır.', '\'Ne var ki\' ayrı, \'ne de olsa\' bitişik yazılır.'], 'Bu bağlaç kalıplarında her sözcük ayrı yazılır.'),
  ('\'Şu zamanda, tam bu sırada\' anlamında kullanılan ve bulunma eki almış zarfın doğru yazımı hangisidir?', 'şu anda', ['şuanda', 'şu an da', 'şu-anda'], '\'Şu\' ve \'an\' ayrı yazılır; bulunma eki \'an\' sözcüğüne bitişir.'),
  ('\'Birdenbire\' ve \'hiçbir zaman\' ifadelerinin yazımı için hangisi doğrudur?', '\'Birdenbire\' bitişik, \'hiçbir zaman\' (\'hiçbir\' bitişik, \'zaman\' ayrı) yazılır.', ['İkisi de bütünüyle bitişik yazılır.', 'İkisi de bütünüyle ayrı yazılır: \'bir den bire\', \'hiç bir zaman\'.', '\'Birdenbire\' ayrı, \'hiçbir zaman\' bitişik yazılır.'], '\'Birdenbire\' tek zarftır; \'hiçbir\' bitişik, ardındaki \'zaman\' ayrı yazılır.'),
  ('\'Hâlbuki\' ile \'oysaki\' sözcükleri ve \'öyle ki\' kalıbı için hangisi doğrudur?', '\'Hâlbuki\' ve \'oysaki\' bitişik, \'öyle ki\' ayrı yazılır.', ['Üçü de bitişik yazılır.', 'Üçü de ayrı yazılır.', '\'Hâlbuki\' ayrı, \'oysaki\' bitişik, \'öyle ki\' bitişik yazılır.'], 'Kalıplaşmış \'ki\'li sözcükler bitişik, bağlaç olarak kullanılan \'ki\' ayrı yazılır.'),
  ('Bir öğrenci, \'Hâlâ\' ve \'hala\' sözcüklerinin farkını yazıda göstermek için şapkanın ne işe yaradığını açıklamak istiyor. Hangi açıklama doğrudur?', 'Şapka, aynı yazılan sözcüklerin anlamını ayırmaya ve \'l\'yi inceltmeye yarar.', ['Şapka, sözcüğün büyük harfle başlayacağını gösterir.', 'Şapka, sözcüğün vurgulu hecesini işaretler.', 'Şapka, yabancı sözcükleri Türkçeden ayırır.'], '\'Hâlâ\' ve \'hala\' sözcüklerinde şapka anlam ayrımı ve uzatma-inceltme işlevi görür.'),
  ('Ayşe şöyle diyor: \'Sert ünsüzle biten her sözcüğe bağlaç olan da/de, ta/te olarak yazılır.\' Bu iddia için hangisi doğrudur?', 'Yanlıştır; bağlaç \'de/da\' benzeşmeye uğramaz, yalnız bulunma eki uğrar.', ['Doğrudur; bağlaç da sert ünsüzden sonra \'ta/te\' olur.', 'Doğrudur; yalnız ünlüyle biten sözcüklerde bağlaç değişir.', 'Yanlıştır; bulunma eki hiç benzeşmeye uğramaz.'], 'Bağlaç \'de/da\' hiçbir zaman \'te/ta\' olmaz; bulunma eki ise sert ünsüzden sonra \'te/ta\' olur.'),
  ('Mert, \'Soru eki bazen sözcüğe bitişik yazılabilir.\' diyor. Bu iddiayı en iyi çürüten örnek hangisidir?', '\'Gelmiş mi?\', \'okuyor mu?\' gibi her durumda ayrı yazılır.', ['\'Gelmişmi?\' biçimi kabul edilir.', '\'Okuyormu?\' yazımı geçerlidir.', 'Soru eki yalnızca isimlerden sonra ayrı yazılır.'], 'Soru eki hiçbir durumda önceki sözcüğe bitişik yazılmaz.'),
  ('Elif şu iddiada bulunuyor: \'Özel adlara gelen her ek kesmeyle ayrılır.\' Hangi örnek bu iddiayı çürütür?', '\'Ankaralı\' sözcüğünde yapım eki kesmeyle ayrılmaz.', ['\'Ali\'nin\' sözcüğünde ek kesmeyle ayrılır.', '\'İzmir\'e\' sözcüğünde ek kesmeyle ayrılır.', '\'Bursa\'da\' sözcüğünde ek kesmeyle ayrılır.'], 'Yalnız çekim ekleri kesmeyle ayrılır; yapım ekleri ayrılmaz.'),
  ('Can, \'Dolaylı soru da soru işaretiyle biter, çünkü içinde soru sözcüğü var.\' diyor. Bu görüş için hangisi doğrudur?', 'Yanlıştır; dolaylı soru bildirme cümlesidir ve nokta ile biter.', ['Doğrudur; soru sözcüğü içeren her cümle soru işaretiyle biter.', 'Doğrudur; nokta yalnız emir cümlelerinde kullanılır.', 'Yanlıştır; dolaylı soru ünlemle biter.'], 'Soru sözcüğü içeren her cümle soru değildir; dolaylı anlatımlar nokta ile bitirilir.'),
  ('Deniz, \'Ölçü birimleri hep büyük harfle ve noktayla yazılır.\' diyor. Bu iddia için hangisi doğrudur?', 'Yanlıştır; çoğu birim simgesi küçük harfle ve noktasız yazılır.', ['Doğrudur; birimler hep büyük harfle yazılır.', 'Doğrudur; birimlerden sonra nokta zorunludur.', 'Yanlıştır; birimler tırnak içine alınır.'], '\'km, kg, cm\' gibi simgeler küçük harfle ve nokta almadan yazılır.'),
  ('Zeynep, \'14:30\' yazımının TDK\'ye uygun olduğunu söylüyor. Bu iddia için hangisi doğrudur?', 'Yanlıştır; TDK saat ve dakikayı nokta ile ayırır: \'14.30\'.', ['Doğrudur; saat daima iki nokta ile yazılır.', 'Doğrudur; yalnız noktalı yazım yanlıştır.', 'Yanlıştır; saat ve dakika arasına virgül konur.'], 'Yazım Kılavuzu\'na göre saat ile dakika nokta ile ayrılır.'),
  ('Burak, \'Başlıklar cümle sayıldığından sonlarına nokta konur.\' diyor. Bu savı hangi ifade çürütür?', 'Başlıkların sonuna nokta konmaz; gerekirse soru ya da ünlem işareti konabilir.', ['Başlıklar yalnız ünlemle biter.', 'Başlıkların sonuna her zaman iki nokta konur.', 'Başlıkların sonuna her zaman noktalı virgül konur.'], 'Başlıklar cümle değil, metnin adıdır; sonlarına nokta konmaz.'),
  ('Selin, \'Kısaltmaya gelen ek kısaltmanın yazılışına göre seçilir.\' diyor. Bu iddia için hangisi doğrudur?', 'Yanlıştır; ek, kısaltmanın okunuşuna göre seçilir: \'TRT\'nin\'.', ['Doğrudur; ek son harfin yazılışına bakılarak seçilir.', 'Doğrudur; ek hiçbir zaman okunuşa bağlı değildir.', 'Yanlıştır; kısaltmalara hiç ek getirilmez.'], '\'TRT\' \'te-re-te\' okunduğundan ek \'nin\' olur.'),
  ('Bir durumdan hoşnutsuzluğu bildirmek anlamındaki sözcüğün TDK\'ye göre doğru yazımı hangisidir?', 'şikâyet', ['şikayet', 'şikaett', 'şikâat'], 'TDK yazımı \'şikâyet\'tir; \'k\'dan sonraki \'a\' şapkayla yazılır.'),
  ('Kesinlikle, hiç şüphesiz anlamındaki sözcüğün doğru yazımı hangisidir?', 'muhakkak', ['muhakak', 'muhakkaak', 'muhhakak'], 'Sözcükte \'k\' ikizleşir: \'muhakkak\'.'),
  ('\'Hiçbirimiz yarınki toplantıya katılamıyacağız, çünkü o gün Ahmetin evinde misafir olacağız.\' cümlesinde kaç yazım yanlışı vardır?', 'iki', ['bir', 'üç', 'dört'], '\'Katılamayacağız\' ve \'Ahmet\'in\' yanlış yazılmıştır; \'yarınki\' doğrudur.'),
  ('\'Kardeşim yalnız kaldığında ağlıyormuş, ben de ona yardım edemiyormuşum.\' cümlesinde kaç yazım yanlışı vardır?', 'hiç', ['bir', 'iki', 'dört'], 'Cümledeki \'yalnız\', \'ben de\', \'yardım edemiyormuşum\' yazımları doğrudur; hata yoktur.'),
  ('\'Prof. Dr. Ayşe Yılmaz 5 km. yürüdü ve bu akşam saat 17,30\'da dönecek.\' cümlesinde kaç yazım ve noktalama yanlışı vardır?', 'iki', ['bir', 'üç', 'dört'], '\'km\' noktasız, saat \'17.30\'da\' biçiminde yazılmalıdır.'),
  ('Hangi cümle yazım ve noktalama bakımından tamamen doğrudur?', 'Ankara\'dan İzmir\'e giden trende yalnız Ali ile Ayşe vardı.', ['Ankara\'dan İzmir\'e giden trende yanlız Ali ile Ayşe vardı.', 'Ankara\'dan İzmire giden trende yalnız Ali ile Ayşe vardı.', 'Ankaradan İzmir\'e giden trende yalnız Ali ile Ayşe vardı.'], 'Özel adlara gelen ekler kesmeyle ayrılır; \'yalnız\' doğru yazılmıştır.'),
  ('Hangi cümlede hiçbir yazım ya da noktalama hatası yoktur?', 'Bu akşam kâğıt toplamaya gitmek istemiyorum, ayrıca hastayım.', ['Bu akşam kağıt toplamaya gitmek istemiyorum, ayrıca hastayım.', 'Bu akşam kâğıt toplamaya gitmek istemiyorum, ayrıca hasta yım.', 'Bu akşam kâğıt toplamaya gitmek istemiyorum. ayrıca hastayım.'], 'Birinci seçenek şapkalı \'kâğıt\', bitişik ek fiil ve doğru noktalamayla yazılmıştır.'),
  ('Hangi cümlede doğrudan aktarma doğru noktalanmıştır?', 'Öğretmenimiz "Yarın sınav var." dedi ve ödevleri topladı.', ['Öğretmenimiz "Yarın sınav var". dedi ve ödevleri topladı.', 'Öğretmenimiz Yarın sınav var. dedi ve ödevleri topladı.', 'Öğretmenimiz "Yarın sınav var." dedi, ve ödevleri topladı.'], 'Tırnak içindeki cümlenin noktası kapanıştan önce gelir; \'ve\'den önce virgül konmaz.'),
  ('Hangi cümle kısaltma ve yüzde yazımı bakımından doğrudur?', 'TBMM\'nin kararına göre %20\'lik indirim yapılacak.', ['TBMM\'nın kararına göre %20\'lik indirim yapılacak.', 'TBMM\'nin kararına göre %20 lik indirim yapılacak.', 'TBMM nin kararına göre %20\'lik indirim yapılacak.'], 'Kısaltmaya gelen ek okunuşa göre seçilir ve kesmeyle ayrılır; rakama gelen ek de kesmeyle yazılır.'),
  ('\'Fetih\' + \'etmek\' birleşimiyle oluşan, bir yeri savaşla ele geçirmek anlamındaki fiilin doğru yazımı hangisidir?', 'fethetmek', ['fetih etmek', 'fetihetmek', 'fetehetmek'], 'Ünlü düşmesi olduğundan fiil bitişik yazılır: \'fethetmek\'.'),
  ('\'Hüküm\' + \'etmek\' birleşiminden oluşan, egemen olmak anlamındaki fiilin doğru yazımı hangisidir?', 'hükmetmek', ['hüküm etmek', 'hükümetmek', 'hüküm-etmek'], 'Ünlü düşmesi olduğundan \'hükmetmek\' bitişik yazılır.'),
  ('\'Keşif\' + \'etmek\' birleşiminden oluşan, bilinmeyeni bulmak anlamındaki fiilin doğru yazımı hangisidir?', 'keşfetmek', ['keşif etmek', 'keşifetmek', 'keşfet-mek'], 'Ünlü düşmesi olduğundan fiil bitişik yazılır: \'keşfetmek\'.'),
  ('\'Öğretmenimiz Ali çok çalışkandır.\' ile \'Öğretmenimiz, Ali, çok çalışkandır.\' cümleleri arasındaki anlam farkı nedir?', 'İlkinde çalışkan olan öğretmen Ali\'dir; ikincisinde Ali\'ye seslenilerek öğretmenin çalışkan olduğu söylenir.', ['İkisi de aynı anlamı taşır.', 'İlkinde Ali\'ye seslenilir; ikincisinde Ali öğretmenin adıdır.', 'İkisinde de çalışkan olan Ali\'nin öğretmenidir.'], 'Virgüller \'Ali\'yi hitap sözü yapar ve anlamı değiştirir.'),
  ('\'Yağmur yağıyordu; yine de piknik yapmaya karar verdik.\' cümlesinde \';\' işareti yerine en az duraklama gösteren hangi işaret konursa anlam bozulmaz?', 'Virgül', ['Üç nokta', 'İki nokta', 'Ünlem'], 'İki bağımsız yargıyı birbirine bağlarken noktalı virgül yerine virgül de kullanılabilir.'),
  ('\'Gelişi güzel\' ve \'çoluk çocuk\' gibi ikilemeler cümlede kullanılırken aralarına ne konur?', 'Hiçbir işaret konmaz; ayrı yazılırlar.', ['Kısa çizgi konur.', 'Virgül konur.', 'Noktalı virgül konur.'], 'İkilemeler arasında noktalama işareti kullanılmaz; sözcükler ayrı yazılır.'),
  ('\'Mevsimler: ilkbahar, yaz, sonbahar, kış.\' gösteriminde iki noktadan sonra büyük harfle başlanmamasının nedeni nedir?', 'Sonrası cümle değil, sıralanan sözcüklerdir.', ['Yanlış yazılmıştır.', 'Büyük harfle başlamak yasaktır.', 'İki nokta sonrası büyük harf gelmez.'], 'İki noktadan sonra tam cümle değil, sözcük sıralaması gelirse küçük harfle devam edilir.'),
];
